navigation-tabs--default.snippet:
import { Component } from '@angular/core';
import { TabsComponent } from './tabs.component';

@Component({
  selector: 'app-demo',
  imports: [TabsComponent],
  template: `
    <app-tabs [tabs]="tabs" [label]="label" [(value)]="value" />
    <div
        role="tabpanel"
        [attr.aria-labelledby]="'app-tab-' + value"
        class="mt-4 text-sm">
        Showing {{ value }} appointments.
    </div>`,
})
export class DemoComponent {
  label = 'Appointments';
  value = 'upcoming';
  tabs = [{value: 'upcoming', label: 'Upcoming'}, {value: 'past', label: 'Past'}, {value: 'cancelled', label: 'Cancelled'}];
  valueChange(event: unknown) {}
}

